package com.bank.lb;

import java.util.*;
import java.util.logging.*;

public class LoadBalancerDemo {
    private static final Logger log = Logger.getLogger("LoadBalancer");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AlbRouter alb = new AlbRouter();
        NlbRouter nlb = new NlbRouter("13.235.10.42"); // static IP per AZ
        LoadBalancerRouter router = new LoadBalancerRouter(alb, nlb);

        log.info(() -> "HTTP /api/transfers -> " + router.route("HTTP", "/api/transfers", 443));
        log.info(() -> "HTTP /api/statements -> " + router.route("HTTP", "/api/statements", 443));
        log.info(() -> "TCP settlement feed -> " + router.route("TCP", null, 9000));
    }
}

// ─── Would be in LoadBalancerRouter.java ───
class LoadBalancerRouter {
    private final AlbRouter alb;
    private final NlbRouter nlb;
    LoadBalancerRouter(AlbRouter alb, NlbRouter nlb) { this.alb = alb; this.nlb = nlb; }

    // HTTP traffic goes to the Layer 7 ALB; raw TCP goes to the Layer 4 NLB.
    String route(String protocol, String path, int port) {
        if ("HTTP".equals(protocol)) {
            return "ALB(L7) -> " + alb.targetGroupFor(path);
        }
        return "NLB(L4) -> " + nlb.forward(port);
    }
}

// ─── Would be in AlbRouter.java ───
class AlbRouter {
    private final Map<String, String> pathRules = Map.of(
        "/api/transfers", "transfer-service-tg",
        "/api/statements", "statement-service-tg");

    String targetGroupFor(String path) {
        return pathRules.getOrDefault(path, "default-tg");
    }
}

// ─── Would be in NlbRouter.java ───
class NlbRouter {
    private final String staticIp;
    NlbRouter(String staticIp) { this.staticIp = staticIp; }

    // NLB preserves the client IP and exposes a fixed IP partners can whitelist.
    String forward(int port) {
        return "staticIP=" + staticIp + " port=" + port + " (client IP preserved)";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
